content.text:
{
  "steps": [
    {
      "title": "დაკეტე წყალი",
      "text": "მოატრიალე ონკანი საათის ისრის მიმართულებით ბოლომდე. შემდეგ მეორეც დაკეტე.",
      "focus": ["p2", "p3"],
      "avoid": [],
      "markers": [
        {"part": "p2", "label": "პირველი ონკანი", "tone": "brand"},
        {"part": "p3", "label": "მეორე ონკანი", "tone": "brand"}
      ],
      "arrows": [
        {"part": "p2", "type": "rotate", "dir": "cw"},
        {"part": "p3", "type": "rotate", "dir": "cw"}
      ],
      "tools": [],
      "warn": "თუ სახელური გაჭედილია, ძალით ნუ დაატრიალებ."
    },
    {
      "title": "ჩადგი ვედრო სიფონის ქვეშ",
      "text": "სიფონში წყალი დგას. გახსნისას ჩამოიღვრება, ამიტომ ვედრო ან ღრმა თასი პირდაპირ მის ქვეშ დადგი.",
      "focus": [],
      "avoid": [],
      "markers": [],
      "arrows": [],
      "tools": ["ვედრო ან ღრმა თასი"],
      "warn": "ვედრო ან თასი ფოტოზე არ ჩანს და მინიჭებული ID არ აქვს; ამიტომ focus ცარიელია."
    },
    {
      "title": "მოუშვი ქანჩი",
      "text": "ეს ქანჩი ჟონავს. ხელით მოუშვი საათის ისრის საწინააღმდეგოდ. პლასტმასისაა, გასაღები არ დაგჭირდება.",
      "focus": ["p4"],
      "avoid": [],
      "markers": [
        {"part": "p4", "label": "სავარაუდოდ ჟონავი შეერთება", "tone": "brand"}
      ],
      "arrows": [
        {"part": "p4", "type": "rotate", "dir": "ccw"}
      ],
      "tools": [],
      "warn": "არჩეულია p4: მარჯვენა ჰორიზონტალურ შეერთებასთან, ქანჩის ქვემოთ, წვეთი ჩანს. ეს მას ყველაზე სავარაუდო სამიზნედ აქცევს, თუმცა ფოტო გაჟონვის წყაროს საბოლოოდ ვერ ადასტურებს. მოხსნისას მილი ხელით დაიჭირე."
    },
    {
      "title": "შეამოწმე შუასადები",
      "text": "მოხსენი სიფონი და ნახე ქანჩის შიგნით რეზინის რგოლი. თუ დაბზარულია ან გვერდზეა გადაწეული, შეცვალე. ზომა: 40 მმ.",
      "focus": ["p5", "p4"],
      "avoid": [],
      "markers": [
        {"part": "p5", "label": "მოსახსნელი სიფონი", "tone": "brand"},
        {"part": "p4", "label": "შუასადების შესამოწმებელი შეერთება", "tone": "brand"}
      ],
      "arrows": [],
      "tools": ["შესაბამისი ზომის ახალი შუასადები, საჭიროების შემთხვევაში"],
      "warn": "რეზინის რგოლი ქანჩის შიგნითაა და ფოტოზე არ ჩანს; p4 აღნიშნავს მხოლოდ მის სავარაუდო შეერთებას. 40 მმ მოცემულია ინსტრუქციაში და ფოტოდან არ დასტურდება — ზომა გადაამოწმე მოხსნილ რგოლზე ან მწარმოებლის მონაცემებით. მხოლოდ გადაწეული, დაუზიანებელი რგოლი შესაძლოა სწორად ჩასმას საჭიროებდეს. სიფონის მოხსნამდე საჭირო იქნება ზედა p1 ქანჩის მოშვებაც."
    },
    {
      "title": "მოუჭირე და შეამოწმე",
      "text": "ხელით მოუჭირე ბოლომდე, შემდეგ კიდევ მეოთხედი ბრუნი. გახსენი წყალი და ერთი წუთი დააკვირდი.",
      "focus": ["p4", "p2", "p3"],
      "avoid": [],
      "markers": [
        {"part": "p4", "label": "მოუჭირე და შეამოწმე გაჟონვა", "tone": "brand"}
      ],
      "arrows": [
        {"part": "p4", "type": "rotate", "dir": "cw"},
        {"part": "p2", "type": "rotate", "dir": "ccw"},
        {"part": "p3", "type": "rotate", "dir": "ccw"}
      ],
      "tools": [],
      "warn": "სამიზნედ კვლავ p4 არის ნავარაუდევი ხილული წვეთის მიხედვით. დამატებითი მეოთხედი ბრუნი უნივერსალური მოთხოვნა არ არის: პლასტმასს ძალა არ დაატანო და მწარმოებლის მითითებას მიჰყევი. თუ p1 მოაშვე, ისიც ხელახლა დაამაგრე. ჩამკეტების გახსნის შემდეგ ნიჟარის ონკანიც გაუშვი, რათა სიფონში წყალი გავიდეს; ნიჟარის ონკანი ფოტოზე არ ჩანს."
    }
  ],
  "unknown_parts": [
    "ვედრო ან ღრმა თასი — ფოტოზე არ ჩანს.",
    "ქანჩის შიგნით მოთავსებული რეზინის შუასადები — დაფარულია; ზომა ფოტოდან ვერ დგინდება.",
    "ნიჟარის ონკანი — ფოტოზე არ ჩანს."
  ]
}
